<script setup lang="ts">
import { computed,ref,watch } from 'vue';import { onLoad,onShow } from '@dcloudio/uni-app';import { useI18n } from 'vue-i18n';import { useMerchantStore } from '@/stores/merchant';import PlanList from './components/PlanList.vue';import CustomerAccountList from './components/CustomerAccountList.vue';import StoredValueRecordList from './components/StoredValueRecordList.vue';
const {t}=useI18n();const merchant=useMerchantStore();const ready=ref(false);const tab=ref('plans');const planNo=ref('');const child=ref<{refresh:()=>unknown}|null>(null);
const tabs=computed(()=>[{key:'plans',label:t('storedValue.plans'),allowed:merchant.can('pay:sv:plan:read')||merchant.can('pay:sv:plan:manage')||merchant.can('pay:sv:recharge:create')},{key:'customers',label:t('storedValue.customers'),allowed:merchant.can('pay:sv:account:read')||(merchant.can('biz:customer')&&merchant.can('pay:sv:recharge:create'))},{key:'records',label:t('storedValue.records'),allowed:merchant.can('pay:sv:account:read')}].filter(x=>x.allowed));
watch(tabs,items=>{if(!items.some(x=>x.key===tab.value))tab.value=items[0]?.key||'';});
onLoad(q=>{if(q?.tab==='customers')tab.value='customers';planNo.value=q?.planNo||'';});
onShow(async()=>{await merchant.ensureStores().catch(()=>null);ready.value=true;if(!tabs.value.some(x=>x.key===tab.value))tab.value=tabs.value[0]?.key||'';void child.value?.refresh();});
</script>
<template><sh-scaffold :title-suffix="merchant.multiStore ? merchant.currentStore?.name : ''" title-key="storedValue.title" :pending="!ready" :denied="ready&&!tabs.length"><sh-tabs :items="tabs" :active="tab" @change="tab=$event"/><PlanList v-if="ready&&tab==='plans'" ref="child"/><CustomerAccountList v-else-if="ready&&tab==='customers'" ref="child" :plan-no="planNo"/><StoredValueRecordList v-else-if="ready&&tab==='records'" ref="child"/></sh-scaffold></template>
